const input = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
const operation = typeof input.operation === 'string' ? input.operation.trim() : '';
const telegram_chat_id = input.telegram_chat_id;
const errors = [];

if (!['save_session', 'read_session'].includes(operation)) {
  errors.push('operation must be save_session or read_session.');
}
if (typeof telegram_chat_id !== 'number' || !Number.isFinite(telegram_chat_id)) {
  errors.push('telegram_chat_id must be a finite number.');
}

let session = input.session;
if (operation === 'save_session') {
  if (!session || typeof session !== 'object' || Array.isArray(session)) {
    errors.push('session must be an object for save_session.');
  } else {
    if (typeof session.state !== 'string') errors.push('session.state must be a string.');
    if (typeof session.novel_uuid !== 'string') errors.push('session.novel_uuid must be a string.');
    if (typeof session.chapter_uuid !== 'string') errors.push('session.chapter_uuid must be a string.');
    if (!session.data || typeof session.data !== 'object' || Array.isArray(session.data)) {
      errors.push('session.data must be an object.');
    }
  }
}

if (errors.length) {
  return [{ json: { ok: false, operation, session: null, error: errors.join(' ') } }];
}

return [{ json: { operation, telegram_chat_id, session: operation === 'save_session' ? {
  state: session.state,
  novel_uuid: session.novel_uuid,
  chapter_uuid: session.chapter_uuid,
  data: session.data,
} : null } }];

const sessions = globalThis.__NOVEL_SESSION__ ??= new Map();
const session = sessions.get($json.telegram_chat_id) ?? null;
return [{ json: { ok: true, operation: 'read_session', session } }];

const sessions = globalThis.__NOVEL_SESSION__ ??= new Map();
