  novel_uuid: $json.session.novel_uuid,
  chapter_uuid: $json.session.chapter_uuid,
  data: $json.session.data,
};
sessions.set($json.telegram_chat_id, session);
return [{ json: { ok: true, operation: 'save_session', session } }];

const result = ($json && typeof $json === 'object' && !Array.isArray($json)) ? $json : {};
return [{ json: result.ok === true
  ? { ok: true, operation: result.operation, session: result.session ?? null }
  : { ok: false, operation: result.operation ?? '', session: null, error: result.error ?? 'Invalid input.' }
}];
